--
-- Table structure for table `pharmacy_sales`
--

DROP TABLE IF EXISTS `pharmacy_sales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pharmacy_sales` (
  `sale_id` int(11) NOT NULL AUTO_INCREMENT,
  `sale_number` varchar(50) NOT NULL,
  `sale_type` enum('COUNTER_SALE','PRESCRIPTION_SALE','IPD_SALE') NOT NULL DEFAULT 'COUNTER_SALE',
  `sale_date` date NOT NULL,
  `patient_type` enum('WALK_IN','REGISTERED','IPD') NOT NULL DEFAULT 'WALK_IN',
  `patient_id` int(11) DEFAULT NULL,
  `customer_name` varchar(150) NOT NULL,
  `customer_mobile` varchar(25) DEFAULT NULL,
  `doctor_name` varchar(150) DEFAULT NULL,
  `prescription_id` int(11) DEFAULT NULL,
  `ipd_admission_id` varchar(50) DEFAULT NULL,
  `ipd_ward` varchar(50) DEFAULT NULL,
  `ipd_bed` varchar(50) DEFAULT NULL,
  `subtotal_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `discount_percent` decimal(5,2) NOT NULL DEFAULT 0.00,
  `discount_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `discount_reason` varchar(255) DEFAULT NULL,
  `discount_authorized_by` int(11) DEFAULT NULL,
  `taxable_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `gst_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `round_off` decimal(6,2) NOT NULL DEFAULT 0.00,
  `grand_total` decimal(12,2) NOT NULL DEFAULT 0.00,
  `paid_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `balance_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `payment_status` enum('UNPAID','PARTIALLY_PAID','PAID','CREDIT','CANCELLED') NOT NULL DEFAULT 'UNPAID',
  `payment_mode` varchar(50) NOT NULL DEFAULT 'CASH',
  `idempotency_key` varchar(100) DEFAULT NULL,
  `status` enum('DRAFT','COMPLETED','CANCELLED') NOT NULL DEFAULT 'COMPLETED',
  `notes` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `cancelled_by` int(11) DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `cancellation_reason` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`sale_id`),
  UNIQUE KEY `sale_number` (`sale_number`),
  UNIQUE KEY `idempotency_key` (`idempotency_key`),
  KEY `idx_sale_type` (`sale_type`),
  KEY `idx_sale_date` (`sale_date`),
  KEY `idx_customer_mobile` (`customer_mobile`),
  KEY `idx_patient_id` (`patient_id`),
  KEY `idx_prescription_id` (`prescription_id`),
  KEY `idx_payment_status` (`payment_status`),
  KEY `idx_created_by` (`created_by`),
  KEY `idx_sales_date_status` (`sale_date`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=111 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

